// v23.xx (spr17), HIS ORDER (2026-10-12) "make them all look better": THE GUN READS. The barrel was a pale blue grey, the lightest
// thing on the gun, so at raid size the weapon read as a pale slab. Receiver and barrel are dark gunmetal now, each with a lit top
// edge, the lower edge of the receiver in shade, a muzzle block on the end of the barrel and a darker magazine; the gun hand holds
// the grip at the end of the sleeve and the support hand rides the handguard, two hands on it. Every family keeps its silhouette
// (v7.77) and the tier colour stays on the top edge. Cosmetic only.
wc.fillStyle='#3e454c'; wc.fillRect(_L-1+ext,-1,_B,2);
wc.fillStyle='#8d98a3'; wc.fillRect(_L-1+ext,-1,_B,0.6);
wc.fillStyle='#1b1f24'; wc.fillRect(_L+_B-2.2+ext,-1.25,1.6,2.5);
wc.fillStyle='#8d99a6'; wc.fillRect(2+ext,-1.6,_L,0.8);
wc.fillStyle='#1f2429'; wc.fillRect(2+ext,0.6,_L,1.0);

check:
{v:'VER',what:'spr17: the gun reads: a dark gunmetal barrel under a lit edge, and a hand on the grip',
 run:function(){
   if(typeof drawOp!=='function'||typeof wc==='undefined'||typeof WEAPONS==='undefined'||!WEAPONS.carbine) return 'SKIP: no drawOp or carbine here';
   var c=document.createElement('canvas'); c.width=300; c.height=300; var x=c.getContext('2d'), w0=wc, bad=[], d;
   try{ x.setTransform(6,0,0,6,100,280); wc=x;
     drawOp(0,0,0,0,'#8a8a8a',0,0,'',0,{moving:false,sprint:false,ads:false,hurt:0,rl:0,bulk:0,build:'lean',hair:'dark',cut:'crop',skin:'fair',own:{wep:WEAPONS.carbine}});
     wc=w0; x.setTransform(1,0,0,1,0,0); d=x.getImageData(0,0,300,300).data; }
   catch(er){ bad.push('threw: '+(er&&er.message||er)); }
   finally{ wc=w0; }
   if(!d) return bad.join('; ');
   function box(u0,u1,v0,v1,fn){ var s=0,n=0,px,py,k; for(py=Math.round(280+6*v0);py<=Math.round(280+6*v1);py++) for(px=Math.round(100+6*u0);px<=Math.round(100+6*u1);px++){ k=(py*300+px)*4; if(d[k+3]<200) continue; if(fn){ if(fn(d[k],d[k+1],d[k+2])) n++; } else { s+=d[k]*0.3+d[k+1]*0.59+d[k+2]*0.11; n++; } } return fn?n:(n?s/n:-1); }
   var bar=box(12.5,16.5,-20.2,-19.2);
   if(bar<0||bar>82) bad.push('the barrel reads '+Math.round(bar)+' bright (want dark gunmetal, under 82; the old barrel was about 100)');
   var hand=box(5.6,7.6,-21.2,-18.8,function(r,g,b){ return r>225&&g>190&&g<225&&b>150&&b<185; });
   if(hand<40) bad.push('no hand on the grip ('+hand+' skin pixels there)');
   return bad.length?bad.join('; '):null; }},
